// Google's favicon service - reliable, returns each brand's logo mark.
//
// Careful: for a domain it can't resolve this returns HTTP 404 (with a generic
// globe PNG in the body, so it *looks* fine in a browser). next.config.ts routes
// these through /_next/image, and Vercel's optimizer answers a non-2xx upstream
// with its own 404 - which turns a dead third-party favicon into a broken image
// on our own domain. BrandLogo's onError monogram can't save it either: a
// crawler never runs the handler. Check a new domain returns 200 before adding
// it, and prefer the exact host that resolves (www.lexisnexis.com works, the
// apex 404s).
const lc = (domain: string) =>
  `https://www.google.com/s2/favicons?domain=${domain}&sz=128`;

// `aiDepth` defaults to "native"; entries where AI is a bolted-on feature set
// it explicitly. See the AiDepth docs in lib/types.ts.
type Seed = Omit<Tool, "listingCost" | "aiDepth"> & {
  listingCost?: string;
  aiDepth?: Tool["aiDepth"];
};
const T = (s: Seed): Tool => {
  const shot = SCREENSHOTS[s.slug];
  return {
    listingCost: "Free · promoted from $49",
    aiDepth: "native",
    ...s,
    // Prepend the captured homepage screenshot as the lead gallery image.
    // Always an explicit array so a re-seed clears stale paths for tools
    // whose screenshot was removed.
    images: shot ? [shot, ...(s.images ?? [])] : (s.images ?? []),
  };
};

